#define BASE UINT32_C(1000000000)

typedef struct {
    uint32_t *digits;
    size_t length;
    size_t capacity;
} BigInteger;

static void allocation_failed(void)
{
    fputs("memory allocation failed\n", stderr);
    exit(EXIT_FAILURE);
}

static void ensure_capacity(BigInteger *value, size_t capacity)
{
    if (value->capacity >= capacity) {
        return;
    }

    size_t new_capacity = value->capacity == 0 ? 1 : value->capacity;
    while (new_capacity < capacity) {
        if (new_capacity > SIZE_MAX / 2) {
            new_capacity = capacity;
            break;
        }
        new_capacity *= 2;
    }

    uint32_t *new_digits = realloc(value->digits, new_capacity * sizeof(*new_digits));
    if (new_digits == NULL) {
        allocation_failed();
    }
    value->digits = new_digits;
    value->capacity = new_capacity;
}

static BigInteger make_zero(void)
{
    BigInteger value = {0};
    ensure_capacity(&value, 1);
    value.digits[0] = 0;
    value.length = 1;
    return value;
}

static void destroy(BigInteger *value)
{
    free(value->digits);
    value->digits = NULL;
    value->length = 0;
    value->capacity = 0;
}

static void add(const BigInteger *left, const BigInteger *right, BigInteger *result)
{
    size_t max_length = left->length > right->length ? left->length : right->length;
    ensure_capacity(result, max_length + 1);

    uint64_t carry = 0;
    for (size_t i = 0; i < max_length; ++i) {
        uint64_t sum = carry;
        if (i < left->length) {
            sum += left->digits[i];
        }
        if (i < right->length) {
            sum += right->digits[i];
        }
        result->digits[i] = (uint32_t)(sum % BASE);
        carry = sum / BASE;
    }

    result->length = max_length;
    if (carry != 0) {
        result->digits[result->length++] = (uint32_t)carry;
    }
}

static int parse_index(const char *text, uintmax_t *index)
{
    if (text[0] == '\0' || text[0] == '-') {
        return 0;
    }

    errno = 0;
    char *end = NULL;
    uintmax_t parsed = strtoumax(text, &end, 10);
    if (errno == ERANGE || *end != '\0') {
        return 0;
    }

    *index = parsed;
    return 1;
}

int main(int argc, char **argv)
{
    if (argc != 2) {
        fprintf(stderr, "usage: %s N\n", argv[0]);
        return EXIT_FAILURE;
    }

    uintmax_t index;
    if (!parse_index(argv[1], &index)) {
        fprintf(stderr, "N must be a non-negative integer\n");
        return EXIT_FAILURE;
    }

    BigInteger previous = make_zero();
