    BigInteger next = make_zero();

    for (uintmax_t i = 0; i < index; ++i) {
        add(&previous, &current, &next);
        BigInteger temporary = previous;
        previous = current;
        current = next;
        next = temporary;
    }

    printf("%" PRIu32, current.digits[current.length - 1]);
    for (size_t i = current.length - 1; i-- > 0;) {
        printf("%09" PRIu32, current.digits[i]);
    }
    putchar('\n');

    destroy(&previous);
    destroy(&current);
    destroy(&next);
    return EXIT_SUCCESS;
}
